function maxNumOfSubstrings(s) {
  const n = s.length;
  const first = new Array(26).fill(n);
  const last = new Array(26).fill(-1);
  for (let i = 0; i < n; i++) {
    const letter = s.charCodeAt(i) - 97;
    first[letter] = Math.min(first[letter], i);
    last[letter] = i;
  }
  const result = [];
  let prevEnd = -1;
  for (let start = 0; start < n; start++) {
    const letter = s.charCodeAt(start) - 97;
    if (start !== first[letter]) continue;
    let end = last[letter];
    let valid = true;
    for (let j = start; j <= end; j++) {
      const inner = s.charCodeAt(j) - 97;
      if (first[inner] < start) {
        valid = false;
        break;
      }
      end = Math.max(end, last[inner]);
    }
    if (!valid) continue;
    if (start > prevEnd) {
      result.push('');
    }
    result[result.length - 1] = s.slice(start, end + 1);
    prevEnd = end;
  }
  return result;
}

