function maxNumOfSubstrings(s) {
  const n = s.length;
  const first = new Map(), last = new Map();
  for (let i = 0; i < n; i++) {
    if (!first.has(s[i])) first.set(s[i], i);
    last.set(s[i], i);
  }
  // List every closed substring s[i..j] by its end j.
  const startsByEnd = Array.from({ length: n }, () => []);
  for (let i = 0; i < n; i++) {
    let lowest = i, highest = i;
    for (let j = i; j < n; j++) {
      lowest = Math.min(lowest, first.get(s[j]));
      highest = Math.max(highest, last.get(s[j]));
      if (lowest < i) break;
      if (highest <= j) startsByEnd[j].push(i);
    }
  }
  // best[p]: the best selection inside the first p characters (most pieces, then least total length).
  const best = [{ count: 0, length: 0, pieces: [] }];
  for (let j = 0; j < n; j++) {
    let current = best[j];
    for (const i of startsByEnd[j]) {
      const before = best[i];
      const option = { count: before.count + 1, length: before.length + (j - i + 1), pieces: [...before.pieces, s.slice(i, j + 1)] };
      if (option.count > current.count || (option.count === current.count && option.length < current.length)) current = option;
    }
    best.push(current);
  }
  return best[n].pieces;
}

