function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = alphabet.length - 1; i > 0; i--) {
    const j = int(0, i);
    [alphabet[i], alphabet[j]] = [alphabet[j], alphabet[i]];
  }
  if (size !== 'large') {
    const letters = alphabet.slice(0, int(1, 5));
    return [Array.from({ length: int(1, 12) }, () => letters[int(0, letters.length - 1)]).join('')];
  }
  if (rand() < 0.2) return [Array.from({ length: 10000 }, () => alphabet[int(0, 25)]).join('')];
  // Build blocks over disjoint letter groups; some blocks are nested inside the previous one, some letters stray.
  let text = '';
  let next = 0;
  while (next < 26) {
    const group = alphabet.slice(next, next + int(1, 3));
    next += group.length;
    const block = Array.from({ length: int(150, 1100) }, () => group[int(0, group.length - 1)]).join('');
    if (text.length > 0 && rand() < 0.35) {
      const at = int(0, text.length);
      text = text.slice(0, at) + block + text.slice(at);
    } else {
      text += block;
    }
  }
  return [text.slice(0, 10000)];
}
